function first(...values) {
  return values.find((value) => value !== undefined && value !== null && String(value).trim() !== '');
}

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch (error) {
    return value;
  }
}

function xmlTag(xml, tag) {
  if (typeof xml !== 'string') return undefined;
  const re = new RegExp(`<${tag}>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([\\s\\S]*?))</${tag}>`, 'i');
  const match = xml.match(re);
  return match ? (match[1] ?? match[2]) : undefined;
}

function normalize(raw) {
  let body = raw.body ?? raw;
  body = parseMaybeJson(body);

  const isXml = typeof body === 'string' && body.trim().startsWith('<');
  const feishuContent = parseMaybeJson(body?.event?.message?.content ?? body?.message?.content);

  const platform = first(
    raw.query?.platform,
    body?.platform,
    isXml ? 'wechat' : undefined,
    body?.FromUserName ? 'wechat' : undefined,
    body?.update_id ? 'telegram' : undefined,
    body?.event ? 'feishu' : undefined,
    'wechat'
  );

  const rawType = first(
    body?.message_type,
    body?.type,
    body?.MsgType,
    body?.message?.voice ? 'voice' : undefined,
    body?.message?.text ? 'text' : undefined,
    isXml ? xmlTag(body, 'MsgType') : undefined,
    'text'
  );

  const text = first(
    body?.text,
    body?.content,
    body?.Content,
    body?.message?.text,
    body?.message?.text?.text,
    feishuContent?.text,
    body?.event?.message?.text,
    isXml ? xmlTag(body, 'Content') : undefined
  );

  const recognition = first(
    body?.recognition,
    body?.Recognition,
    body?.speech_text,
    body?.transcript,
    body?.asr_text,
    isXml ? xmlTag(body, 'Recognition') : undefined
  );

  const audioUrl = first(
    body?.audio_url,
    body?.voice_url,
    body?.media_url,
    body?.file_url,
    body?.audio?.url,
    body?.voice?.url,
    body?.message?.voice?.file_url
  );

  const mediaId = first(
    body?.media_id,
    body?.MediaId,
    isXml ? xmlTag(body, 'MediaId') : undefined,
    body?.message?.voice?.file_id
  );

  const senderId = first(
    body?.sender_id,
    body?.from_user,
    body?.FromUserName,
    isXml ? xmlTag(body, 'FromUserName') : undefined,
    body?.message?.from?.id,
    body?.event?.sender?.sender_id?.open_id,
    'unknown-sender'
  );

  const chatId = first(
    body?.chat_id,
    body?.conversation_id,
    body?.chat?.id,
    body?.message?.chat?.id,
    body?.event?.message?.chat_id,
    senderId
  );

  const messageId = first(
    body?.message_id,
    body?.MsgId,
    isXml ? xmlTag(body, 'MsgId') : undefined,
    body?.message?.message_id,
    body?.event?.message?.message_id,
    `${Date.now()}`
  );

  const inputText = first(text, recognition);
  const messageType = String(rawType).toLowerCase().includes('voice') || audioUrl || mediaId ? 'voice' : 'text';

  return {
    platform,
    message_type: messageType,
    sender_id: String(senderId),
    chat_id: String(chatId),
    message_id: String(messageId),
    input_text: inputText ? String(inputText).trim() : '',
    audio_url: audioUrl ? String(audioUrl).trim() : '',
    media_id: mediaId ? String(mediaId).trim() : '',
    raw_payload: body
  };
}

return $input.all().map((item) => ({ json: normalize(item.json) }));

let parsed;
try {
  parsed = typeof query === 'string' ? JSON.parse(query) : query;
} catch (error) {
  parsed = { task: String(query || '') };
}

return JSON.stringify({
  tool: 'echo_task_tool',
  ok: true,
  received: parsed,
  message: '测试工具已被 AI Agent 成功调用。',
  next_step_hint: '后续可以把这个工具替换成创建待办、查询数据库、调用内部 API 或执行子 workflow。',
  executed_at: new Date().toISOString()
});

const source = $items('Normalize Inbound Message')[0]?.json ?? {};
return $input.all().map((item) => {
  const reply = item.json.output ?? item.json.text ?? item.json.response ?? JSON.stringify(item.json);
  return {
    json: {
      ok: true,
      platform: source.platform,
      chat_id: source.chat_id,
      sender_id: source.sender_id,
      message_id: source.message_id,
      reply,
      raw_agent_output: item.json
    }
  };
});

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value || {};
  try {
    return JSON.parse(value);
  } catch (error) {
    return { query: value };
  }
}

function first(...values) {
  return values.find((value) => value !== undefined && value !== null && String(value).trim() !== '');
}

function inferLocation(input) {
  const text = String(first(input.location, input.city, input.query, input.text, '')).trim();
  const explicit = String(first(input.location, input.city, '')).trim();
  if (explicit) return explicit;

  const match = text.match(/(?:在|查一下|查询)?([\u4e00-\u9fa5A-Za-z\s.-]{2,40})(?:今天|明天|后天|未来|天气|温度|下雨|降雨|会不会|多少度)/);
  if (match && match[1]) {
    const location = match[1].replace(/^(我想知道|请问|帮我看|帮我查|查询|查一下|在)/, '').trim();
    if (location && !/^(今天|明天|未来|天气)$/.test(location)) return location;
  }

  return '香港';
}

function weatherCodeLabel(code) {
  const labels = {
    0: '晴朗',
    1: '大致晴朗',
    2: '局部多云',
    3: '阴天',
    45: '有雾',
    48: '雾凇',
    51: '小毛毛雨',
    53: '中等毛毛雨',
    55: '强毛毛雨',
    61: '小雨',
    63: '中雨',
    65: '大雨',
    71: '小雪',
    73: '中雪',
    75: '大雪',
    80: '小阵雨',
    81: '中等阵雨',
    82: '强阵雨',
    95: '雷雨',
    96: '雷雨伴小冰雹',
    99: '雷雨伴大冰雹',
  };
  return labels[code] || '未知';
}

const input = parseMaybeJson(query);
const locationName = inferLocation(input);
const geoUrl = 'https://geocoding-api.open-meteo.com/v1/search?name='
  + encodeURIComponent(locationName)
  + '&count=1&language=zh&format=json';

const geoResponse = await fetch(geoUrl);
if (!geoResponse.ok) {
  return JSON.stringify({ ok: false, error: 'geocoding_failed', status: geoResponse.status, location: locationName });
}

const geo = await geoResponse.json();
const place = geo.results && geo.results[0];
if (!place) {
  return JSON.stringify({ ok: false, error: 'location_not_found', location: locationName });
}

const forecastUrl = 'https://api.open-meteo.com/v1/forecast'
  + '?latitude=' + encodeURIComponent(place.latitude)
  + '&longitude=' + encodeURIComponent(place.longitude)
  + '&current=temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,rain,weather_code,wind_speed_10m'
  + '&hourly=temperature_2m,precipitation_probability,precipitation,weather_code'
  + '&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum,weather_code'
  + '&timezone=auto&forecast_days=3';

const forecastResponse = await fetch(forecastUrl);
if (!forecastResponse.ok) {
  return JSON.stringify({ ok: false, error: 'forecast_failed', status: forecastResponse.status, location: locationName });
}

const forecast = await forecastResponse.json();
const current = forecast.current || {};
const daily = forecast.daily || {};

const days = (daily.time || []).map((date, index) => ({
  date,
  weather: weatherCodeLabel(daily.weather_code && daily.weather_code[index]),
  temperature_min_c: daily.temperature_2m_min && daily.temperature_2m_min[index],
  temperature_max_c: daily.temperature_2m_max && daily.temperature_2m_max[index],
  precipitation_probability_max_percent: daily.precipitation_probability_max && daily.precipitation_probability_max[index],
  precipitation_sum_mm: daily.precipitation_sum && daily.precipitation_sum[index],
}));

return JSON.stringify({
  ok: true,
  provider: 'Open-Meteo',
  requested_location: locationName,
  resolved_location: {
    name: place.name,
    country: place.country,
    admin1: place.admin1,
    latitude: place.latitude,
    longitude: place.longitude,
    timezone: forecast.timezone,
  },
  current: {
    time: current.time,
    weather: weatherCodeLabel(current.weather_code),
    temperature_c: current.temperature_2m,
    apparent_temperature_c: current.apparent_temperature,
    relative_humidity_percent: current.relative_humidity_2m,
    precipitation_mm: current.precipitation,
    rain_mm: current.rain,
    wind_speed_kmh: current.wind_speed_10m,
  },
  daily: days,
  guidance: '请基于 current 和 daily 字段，用中文回答用户，并在需要时输出 Markdown 表格。',
});

function extractOrderId(text) {
  const match = String(text || '').match(/\bord_[0-9A-Za-z]+\b/i);
  return match ? match[0].toLowerCase() : '';
}

function hasAfterSalesKeyword(text) {
  const value = String(text || '').toLowerCase();
  return [
    '订单',
    '物流',
    '售后',
    '退款',
    '退货',
    '换货',
    '发货',
    '配送',
    '投诉',
    'order',
    'shipment',
    'delivery',
    'refund',
    'return'
  ].some((keyword) => value.includes(keyword));
}

return $input.all().map((item) => {
  const text = item.json.input_text || '';
  const orderId = extractOrderId(text);
  return {
    json: {
      ...item.json,
      order_id: orderId,
      is_after_sales_order: Boolean(orderId && hasAfterSalesKeyword(text))
    }
  };
});

function afterSalesSuggestion(shipment) {
  const delayDays = Number(shipment.delay_days || 0);
  if (delayDays > 0 || shipment.status === 'delayed') {
    return '建议客服主动安抚客户，并跟进物流延迟原因。';
  }
  return '建议告知客户订单状态正常，无需人工介入。';
}

function sourcePayload(item) {
  return {
    platform: item.platform,
    chat_id: item.chat_id,
    sender_id: item.sender_id,
    message_id: item.message_id
  };
}

return await Promise.all($input.all().map(async (item) => {
  const source = item.json;
  const orderId = source.order_id;
  try {
    if (!orderId) {
      return {
        json: {
          ok: true,
          ...sourcePayload(source),
          reply: '请提供订单号，例如 ord_100。',
          raw_agent_output: { deterministic_after_sales_tool: true, ok: false, error: 'missing_order_id' }
        }
      };
    }

    const orderUrl = 'http://mock-api:8000/orders/' + encodeURIComponent(orderId);
    const order = await this.helpers.httpRequest({
      method: 'GET',
      url: orderUrl,
      json: true
    });

    const shipmentUrl = 'http://mock-api:8000/shipments/' + encodeURIComponent(order.shipment_id);
    const shipment = await this.helpers.httpRequest({
      method: 'GET',
      url: shipmentUrl,
      json: true
    });
    const reply = [
      '订单 ' + order.order_id + ' 查询成功。',
      '订单状态：' + order.status,
      '物流商：' + shipment.carrier,
      '物流状态：' + shipment.status,
      '延迟天数：' + shipment.delay_days,
      '行动建议：' + afterSalesSuggestion(shipment)
    ].join('\n');

    return {
      json: {
        ok: true,
        ...sourcePayload(source),
        reply,
        raw_agent_output: {
          deterministic_after_sales_tool: true,
          ok: true,
          order,
          shipment
        }
      }
    };
  } catch (error) {
    return {
      json: {
        ok: true,
        ...sourcePayload(source),
        reply: '订单 ' + (orderId || '') + ' 查询时出现系统异常，请人工跟进。',
        raw_agent_output: {
          deterministic_after_sales_tool: true,
          ok: false,
          error: 'runtime_error',
          message: error && error.message ? error.message : String(error)
        }
      }
    };
  }
}));

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value || {};
  try {
    return JSON.parse(value);
  } catch (error) {
    return { query: value };
  }
}

function first(...values) {
  return values.find((value) => value !== undefined && value !== null && String(value).trim() !== '');
}

function extractOrderId(input) {
  const text = String(first(input.order_id, input.orderId, input.query, input.text, '')).trim();
  const match = text.match(/\bord_[0-9A-Za-z]+\b/i);
  return match ? match[0].toLowerCase() : '';
}

try {
  const input = parseMaybeJson(query);
  const orderId = extractOrderId(input);
  if (!orderId) {
    return JSON.stringify({ ok: false, error: 'missing_order_id', message: '请提供订单号，例如 ord_100。' });
  }

  const orderUrl = 'http://mock-api:8000/orders/' + encodeURIComponent(orderId);
  const orderResponse = await fetch(orderUrl);
  if (!orderResponse.ok) {
    return JSON.stringify({ ok: false, error: 'order_lookup_failed', step: 'fetch_order', status: orderResponse.status, order_id: orderId });
  }
  const orderText = await orderResponse.text();
  const order = JSON.parse(orderText);
  if (!order.shipment_id) {
    return JSON.stringify({ ok: false, error: 'missing_shipment_id', step: 'parse_order', order_id: orderId, order });
  }

  const shipmentUrl = 'http://mock-api:8000/shipments/' + encodeURIComponent(order.shipment_id);
  const shipmentResponse = await fetch(shipmentUrl);
  if (!shipmentResponse.ok) {
    return JSON.stringify({ ok: false, error: 'shipment_lookup_failed', step: 'fetch_shipment', status: shipmentResponse.status, order_id: orderId, shipment_id: order.shipment_id });
  }
  const shipmentText = await shipmentResponse.text();
  const shipment = JSON.parse(shipmentText);

  const suggestion = Number(shipment.delay_days || 0) > 0 || shipment.status === 'delayed'
    ? '建议客服主动安抚客户，并跟进物流延迟原因。'
    : '建议告知客户订单状态正常，无需人工介入。';
  return [
    '查询成功。',
    '订单号：' + order.order_id,
    '订单状态：' + order.status,
    '物流商：' + shipment.carrier,
    '物流状态：' + shipment.status,
    '延迟天数：' + shipment.delay_days,
    '行动建议：' + suggestion
  ].join('\n');
} catch (error) {
  return JSON.stringify({
    ok: false,
    error: 'tool_runtime_error',
    step: 'unexpected_exception',
    message: error && error.message ? error.message : String(error)
  });
}
